package com.cropdeal.review;
import com.cropdeal.review.client.*; import com.cropdeal.review.dto.*; import com.cropdeal.review.entity.*; import com.cropdeal.review.repository.*; import com.cropdeal.review.service.*; import com.cropdeal.review.security.*; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.util.*;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class ReviewServiceTest {
 @Mock ReviewRepository repo; @Mock OrderClient orders; @Mock UserClient users; @BeforeEach void set(){MockitoAnnotations.openMocks(this);var a=new UsernamePasswordAuthenticationToken("farmer@test.com",null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_FARMER")));a.setDetails(100L);SecurityContextHolder.getContext().setAuthentication(a);}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void farmerCanReviewCompletedOrder(){ReviewService s=new ReviewService(repo,orders,users,"test-key");OrderResponse o=new OrderResponse();o.setId(1L);o.setFarmerId(10L);o.setDealerId(20L);o.setStatus("COMPLETED");UserResponse u=new UserResponse();u.setId(10L);u.setAuthUserId(100L);u.setRole("FARMER");when(orders.getOrder(eq(1L),any())).thenReturn(o);when(users.getByAuth(100L)).thenReturn(u);when(repo.findByOrderIdAndReviewerIdAndReviewType(1L,10L,ReviewType.FARMER_TO_DEALER)).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(inv->inv.getArgument(0));ReviewRequest q=new ReviewRequest();q.setOrderId(1L);q.setRating(5);q.setReview("Good");ReviewResponse r=s.create(q);Assertions.assertEquals(5,r.getRating());Assertions.assertEquals(20L,r.getTargetUserId());}
 @Test void duplicateReviewRejected(){ReviewService s=new ReviewService(repo,orders,users,"test-key");OrderResponse o=new OrderResponse();o.setId(1L);o.setFarmerId(10L);o.setDealerId(20L);o.setStatus("COMPLETED");UserResponse u=new UserResponse();u.setId(10L);u.setAuthUserId(100L);u.setRole("FARMER");when(orders.getOrder(eq(1L),any())).thenReturn(o);when(users.getByAuth(100L)).thenReturn(u);when(repo.findByOrderIdAndReviewerIdAndReviewType(1L,10L,ReviewType.FARMER_TO_DEALER)).thenReturn(Optional.of(new Review()));ReviewRequest q=new ReviewRequest();q.setOrderId(1L);q.setRating(4);Assertions.assertThrows(IllegalArgumentException.class,()->s.create(q));}
}
